import {money,cents,today} from './domain.mjs';
import {investmentData,savePosition,saveStockEvent,deleteStockEvent,deletePosition,saveStockPrice,saveInvestorProfile,portfolio,coachFacts,investmentScenario,validateQuoteFile,price4,stockShares,importStockRows} from './investment-core.mjs';
import {stockGross,stockKey} from './investment-schema.mjs';
const MARKET_LINKS={TWSE:'https://openapi.twse.com.tw/',TPEX:'https://www.tpex.org.tw/openapi/'};
export function createInvestmentUI(c){
  const {E,I,toast,openSheet}=c,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const state=()=>c.getState(),data=()=>investmentData(state()),scope=()=>c.getStorageKey();
  let quotes=[],quoteInfo=null,quoteError='',loading=false,tab='overview',search='',generation=0,controller=null,selectedImages=[];
  const metric=(n,unknown='待補資料')=>n===null?unknown:money(n),px=n=>new Intl.NumberFormat('zh-TW',{maximumFractionDigits:4}).format(n/10000);
  const input=(label,id,value='',extra='')=>`<label class="field">${label}<input id="${id}" value="${E(value)}" ${extra}></label>`;
  const select=(label,id,rows,value)=>`<label class="field">${label}<select id="${id}">${rows.map(([v,l])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(l)}</option>`).join('')}</select></label>`;
  const err='<div id="stock-error" class="inline-error" role="alert"></div>';
  const fail=e=>{if($('#stock-error'))$('#stock-error').textContent=e.message;else toast(e.message)};
  const cancel=()=>{controller?.abort();controller=null;generation++;selectedImages=[];};
  function sheet(title,html){cancel();openSheet(title,html);}
  $('#sheet').addEventListener('close',cancel);
  const finish=(next,message)=>{if(c.commit(next)){c.render();$('#sheet').close();toast(message);return true;}return false;};
  async function loadQuotes(){if(loading)return;loading=true;try{const res=await fetch('./stock-quotes.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('行情更新暫時不可用');const next=validateQuoteFile(await res.json());quotes=next.quotes;quoteInfo=next;quoteError='';}catch(e){quoteError=e.message+'；可填寫手動價格，既有持股不受影響。';}finally{loading=false;c.render();}}
  function priceNotice(){const dates=[...new Set(quotes.map(q=>q.date))].sort(),date=dates.at(-1);return `<div class="notice stock-price-notice"><span>${loading?'正在讀取收盤資料…':quotes.length?'官方行情最近日期：'+E(date)+'（各標的日期見持股卡）':'尚未載入官方收盤資料'}。這不是盤中即時行情。</span><button class="text-btn" id="stock-refresh" ${loading?'disabled':''}>${I('refresh')}重新載入</button>${quoteError?`<p class="help">${E(quoteError)}</p>`:''}${quoteInfo?.sources.map(s=>`<small>${s.market}：${E(s.status)}${s.date?' · '+E(s.date):''}</small>`).join('')||''}</div>`;}
  function homePanel(){const p=portfolio(state(),quotes);return `<div class="card stock-home"><div><span class="eyebrow">YOUR INVESTMENTS</span><h2>股票投資</h2><p class="help">${p.held.length?`${p.held.length}個持股 · 市值 <span class="sensitive">${metric(p.value,'部分價格待補')}</span>`:'用多張截圖建立持股，再看損益與配置。'}</p></div><button class="secondary" data-page="stocks">開啟投資分頁 ${I('right')}</button></div>`;}
  function page(){const p=portfolio(state(),quotes);return `<div class="page-title"><div><div class="eyebrow">MAKE ROOM FOR YOUR FUTURE</div><h1>讓投資，也心裡有數。</h1><p class="subtitle">台股與 ETF · 持股、股利與下一步，一起整理。</p></div><div class="controls"><button class="secondary" id="stock-import">${I('camera')}匯入多張截圖</button><button class="primary" id="stock-new">${I('plus')}新增持股</button></div></div><div class="tabs stock-tabs">${[['overview','持股總覽'],['activity','買賣與股利'],['coach','投資教練']].map(([id,label])=>`<button data-stock-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div>${priceNotice()}${tab==='overview'?overview(p):tab==='activity'?activity(p):coach(p)}<p class="help stock-footnote">投資與一般收支獨立統計。買賣不會新增日常支出或收入，股利不會自動重複入帳。價格與建議以顯示日期為準，不連接券商、不自動下單。官方行情來源：<a href="${MARKET_LINKS.TWSE}" target="_blank" rel="noopener">證交所</a>／<a href="${MARKET_LINKS.TPEX}" target="_blank" rel="noopener">櫃買中心</a>。</p>`;}
  function overview(p){const rows=p.rows.filter(r=>(r.code+' '+r.name).toLowerCase().includes(search.toLowerCase()));return `<div class="stock-stats">${[['目前持股市值',p.value,p.missingPrices?`${p.missingPrices}個持股缺價格，已知部分 ${money(p.knownValue)}`:'收盤／手動價格估算'],['未實現損益',p.unrealized,p.missingCost?'部分取得成本未知':'市值減剩餘成本，未扣未來賣出費稅'],['已實現損益',p.realized,p.unknownSales?'部分歷史賣出成本未知':'依移動平均成本計算，已扣填入費稅'],['已領現金股利',p.dividends,'僅統計實際填入的淨入帳金額']].map(([label,n,note])=>`<div class="card"><small>${label}</small><strong class="sensitive">${metric(n)}</strong><p class="help">${E(note)}</p></div>`).join('')}</div><div class="card stock-total"><span>已記錄期間合計損益 <strong class="sensitive">${metric(p.totalGain)}</strong></span><small>未實現＋已實現＋實收股利；持股起點之前的歷史未提供時不含該期間。</small></div><div class="filters"><label class="search">${I('search')}<input id="stock-search" aria-label="搜尋股票" placeholder="搜尋代號或名稱" value="${E(search)}"></label><button class="secondary" id="stock-event-add">記錄買賣／股利</button></div>${!p.rows.length?'<div class="card empty">先新增持股，或上傳券商截圖。<br><small>不知道成本可留空，稍後補齊。</small></div>':`<div class="stock-grid">${rows.map(r=>`<article class="card stock-position"><div class="card-heading"><div><span class="pill">${r.code} · ${r.market}</span><h2>${E(r.name)}</h2><small>${r.kind==='etf'?'ETF':r.kind==='stock'?'股票':'類型待確認'} · ${r.shares?new Intl.NumberFormat('zh-TW').format(r.shares)+' 股':'已出清／尚未買進'}</small></div><button class="text-btn" data-stock-detail="${E(r.id)}">管理</button></div><div class="stock-position-value sensitive">${metric(r.value,'價格待補')}</div><div class="credit-breakdown"><div><small>平均取得成本／股</small><strong class="sensitive">${r.average===null?'未知':'$'+new Intl.NumberFormat('zh-TW',{maximumFractionDigits:4}).format(r.average)}</strong></div><div><small>未實現損益</small><strong class="sensitive">${metric(r.unrealized)}</strong></div></div><p class="help">${r.quote?`價格 ${px(r.quote.price4)} · ${r.quote.date} · ${r.quote.source==='manual'?'手動':r.quote.source+' 收盤'}`:'沒有可用價格，請更新或手動填寫。'}${p.value&&r.value!==null?' · 市值占比 '+(r.value/p.value*100).toFixed(1)+'%':''}</p><div class="row stock-row"><button class="secondary" data-stock-trade="${E(r.id)}">記錄交易</button><button class="text-btn" data-stock-price="${E(r.id)}">填價格</button></div></article>`).join('')}</div>`}`;}
  function activity(p){const names=new Map(p.rows.map(r=>[r.id,r]));return `<div class="card"><div class="card-heading"><h2>投資紀錄</h2><button class="primary" id="stock-event-add">新增紀錄</button></div><p class="help">同日交易依新增順序計算移動平均成本；截圖跨頁時請核對重複與實際順序。費稅請填券商實際金額，不自動推定費率。</p>${[...data().events].sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order).map(e=>`<div class="due-row"><div><strong>${E(names.get(e.positionId)?.name||'')} · ${{buy:'買進',sell:'賣出',dividend:'現金股利',split:'股數調整'}[e.type]}</strong><small>${e.date} · ${e.type==='dividend'?`實收 <span class="sensitive">${money(e.amount)}</span>`:e.type==='split'?`調整後 ${e.sharesAfter} 股（總成本不變）`:`${e.shares} 股 × <span class="sensitive">${px(e.price4)}</span> · 費用／稅 <span class="sensitive">${money(e.fee+e.tax)}</span>`}</small></div><button class="text-btn" data-stock-event-edit="${E(e.id)}">編輯</button><button class="text-btn" data-stock-event-delete="${E(e.id)}">刪除</button></div>`).join('')||'<p class="help">目前沒有買賣或股利紀錄。持股起點不會被當成新的買進。</p>'}</div>`;}
  function coach(p){const f=coachFacts(state(),quotes),risk={conservative:'保守',balanced:'均衡',growth:'積極'}[p.profile.risk];return `<div class="card stock-coach-goal"><div><span class="eyebrow">YOUR PLAN, YOUR PACE</span><h2>先有方向，再做決定。</h2><p class="help">目前偏好：${risk} · ${p.profile.horizon}年 · 每月預算 <span class="sensitive">${p.profile.monthlyBudget?money(p.profile.monthlyBudget):'尚未設定'}</span> · 集中度提醒 ${p.profile.concentration}%（可自訂）</p></div><button class="secondary" id="stock-profile">設定目標</button></div><div class="card"><h2>依帳目計算的小提醒</h2>${f.findings.map(t=>`<p class="help">• ${E(t)}</p>`).join('')}<p class="help">集中度僅比較股票持股市值，不含現金或其他資產。ETF按整檔計算，不能直接等同單一公司的風險；未穿透成分股。提醒不需要 AI Key。</p></div><div class="stock-options">${f.options.map(o=>`<div class="card"><h3>${E(o.title)}</h3><p class="help">${E(o.text)}</p></div>`).join('')}</div><div class="card"><div class="card-heading"><h2>把下一步，先試算一次。</h2><button class="secondary" id="stock-scenario" ${p.rows.length?'':'disabled'}>投入／減碼情境</button></div><p class="help">比較一筆交易對股數、持股比重及投入／回收資金的影響，不改動帳本。</p><button class="primary" id="stock-ai-coach">${I('spark')}請 AI 整理理由與行動條件</button><p class="help">下一步會顯示要送出的投資摘要；確認後才傳給 Google，沿用已保存的 AI Key。</p></div>`;}
  function positionSheet(id=null){const old=data().positions.find(p=>p.id===id);const locked=old&&data().events.some(e=>e.positionId===id);const p=old||{market:'TWSE',code:'',name:'',kind:'unknown',openingDate:today(),openingShares:0,openingCost:null};sheet(old?'編輯持股資料':'建立持股起點',`<form id="stock-position-form">${select('市場','position-market',[['TWSE','上市 TWSE'],['TPEX','上櫃 TPEX']],p.market)}<div class="row">${input('股票代號（保留前導0）','position-code',p.code,'required maxlength="6" placeholder="0050"')}${input('名稱','position-name',p.name,'required maxlength="80"')}</div>${select('類型','position-kind',[['unknown','待確認'],['stock','股票'],['etf','ETF']],p.kind)}${input('這份持股的起算日期','position-date',p.openingDate,'type="date" required max="'+today()+'"')}<div class="row">${input('目前持有股數','position-shares',p.openingShares,'type="number" inputmode="numeric" min="0" max="1000000000" step="1" required')}${input('取得總成本（NT$，未知留空）','position-cost',p.openingCost===null?'':p.openingCost/100,'type="number" inputmode="decimal" min="0" max="10000000000" step="0.01"')}</div><p class="help">這是起點庫存，不是新增買進。填取得總成本（含已知費用），不要填目前市值；未知成本會標為待補，不猜損益。起點之前的買賣／股利未提供時不計入歷史績效。</p>${err}<button class="primary full">確認持股起點</button></form>`);if(locked){for(const name of ['position-market','position-code','position-date','position-shares','position-cost'])$('#'+name).disabled=true;}$('#stock-position-form').onsubmit=e=>{e.preventDefault();try{const shares=Number($('#position-shares').value),cost=$('#position-cost').value.trim();finish(savePosition(state(),{market:$('#position-market').value,code:$('#position-code').value.trim().toUpperCase(),name:$('#position-name').value.trim(),kind:$('#position-kind').value,openingDate:$('#position-date').value,openingShares:shares,openingCost:cost===''?(shares?null:0):cents(cost)},id),'持股已儲存，未增加一般支出')}catch(e){fail(e)}};}
  function detail(id){const r=portfolio(state(),quotes).rows.find(p=>p.id===id);if(!r)return;sheet(r.name+' · 持股管理',`<p class="help">${r.code} · 起點 ${r.openingDate} · 起點庫存 ${r.openingShares}股 · 目前 ${r.shares}股</p><div class="row stock-row"><button class="primary" id="detail-trade">記錄交易／股利</button><button class="secondary" id="detail-price">填寫手動價格</button><button class="secondary" id="detail-opening">名稱／類型與起點</button></div><p class="help">分割或合併請記錄「股數調整」，總成本維持不變。交易存在時可修改名稱與類型，起點股數與成本會鎖定，避免把新的庫存截圖再次相加。</p><button class="text-btn danger" id="detail-delete">刪除此持股起點</button>${err}`);$('#detail-trade').onclick=()=>eventSheet(id);$('#detail-price').onclick=()=>priceSheet(id);$('#detail-opening').onclick=()=>positionSheet(id);$('#detail-delete').onclick=()=>{if(confirm('刪除此持股起點？交易存在時會停止刪除，完整備份與本機歷史可用於復原。'))try{finish(deletePosition(state(),id),'持股起點已刪除')}catch(e){fail(e)}};}
  function eventSheet(positionId=null,id=null){if(!data().positions.length){toast('請先新增持股起點，沒有既有庫存可填0股');positionSheet();return;}const old=data().events.find(e=>e.id===id),e=old||{positionId:positionId||data().positions[0].id,type:'buy',date:today(),shares:0,price4:null,fee:0,tax:0,amount:0,sharesAfter:0};sheet(old?'修改投資紀錄':'記錄買賣／股利',`<form id="stock-event-form">${select('持股','event-position',data().positions.map(p=>[p.id,p.code+' '+p.name]),e.positionId)}${select('紀錄類型','event-type',[['buy','買進'],['sell','賣出'],['dividend','實收現金股利'],['split','分割／合併股數調整']],e.type)}${input('實際日期','event-date',e.date,'type="date" required max="'+today()+'"')}<div id="event-trade-fields"><div class="row">${input('數量','event-shares',e.shares||'','type="number" min="0.001" max="1000000000" step="any" inputmode="decimal"')}${select('數量單位','event-unit',[['shares','股'],['lots','張（1000股）']],'shares')}</div>${input('每股成交單價（NT$）','event-price',e.price4?e.price4/10000:'','type="number" min="0.0001" max="1000000" step="0.0001" inputmode="decimal"')}${input('實際手續費（NT$，沒有請填0）','event-fee',e.fee/100||0,'type="number" min="0" step="0.01"')}<div id="event-tax-field">${input('實際交易稅（NT$）','event-tax',e.tax/100||0,'type="number" min="0" step="0.01"')}</div></div><div id="event-dividend-field">${input('實際淨入帳股利（NT$）','event-dividend',e.amount?e.amount/100:'','type="number" min="0.01" step="0.01"')}</div><div id="event-split-field">${input('調整後總持股股數','event-after',e.sharesAfter||'','type="number" min="1" step="1"')}<p class="help">只改變股數，總成本不變；零股現金補償不自動推算。</p></div><p class="help">投資交易不會另記一般收支。同日紀錄依新增順序計算；費稅以券商資料為準，空白費稅視為0，請確認。</p>${err}<button class="primary full">確認投資紀錄</button></form>`);
    const toggle=()=>{const type=$('#event-type').value;for(const [container,show] of [['event-trade-fields',['buy','sell'].includes(type)],['event-tax-field',type==='sell'],['event-dividend-field',type==='dividend'],['event-split-field',type==='split']]){const el=$('#'+container);el.hidden=!show;el.querySelectorAll('input').forEach(i=>{i.disabled=!show;i.required=show;});}if(type!=='sell')$('#event-tax').disabled=true;};$('#event-type').onchange=toggle;toggle();$('#stock-event-form').onsubmit=ev=>{ev.preventDefault();try{const type=$('#event-type').value,row={positionId:$('#event-position').value,type,date:$('#event-date').value};if(['buy','sell'].includes(type))Object.assign(row,{shares:stockShares($('#event-shares').value,$('#event-unit').value),price4:price4($('#event-price').value),fee:cents($('#event-fee').value||0),tax:type==='sell'?cents($('#event-tax').value||0):0});if(type==='dividend')row.amount=cents($('#event-dividend').value);if(type==='split')row.sharesAfter=Number($('#event-after').value);finish(saveStockEvent(state(),row,id),'投資紀錄已儲存')}catch(e){fail(e)}};
  }
  function priceSheet(id){const p=portfolio(state(),quotes).rows.find(p=>p.id===id);sheet('手動價格 · '+p.name,`<form id="stock-price-form">${input('價格日期','price-date',today(),'type="date" required max="'+today()+'"')}${input('每股價格（NT$）','price-value',p.quote?p.quote.price4/10000:'','type="number" step="0.0001" min="0.0001" required')}<p class="help">採日期較新的手動／官方價格；同日以手動價格優先。此價格只供估算，不是成交紀錄。</p>${err}<button class="primary full">儲存手動價格</button></form>`);$('#stock-price-form').onsubmit=e=>{e.preventDefault();try{finish(saveStockPrice(state(),{market:p.market,code:p.code,date:$('#price-date').value,price4:price4($('#price-value').value)}),'手動價格已儲存')}catch(e){fail(e)}};}
  function profileSheet(){const p=data().profile;sheet('我的投資目標',`<form id="stock-profile-form">${select('風險偏好','profile-risk',[['conservative','保守'],['balanced','均衡'],['growth','積極']],p.risk)}${input('每月預計投入（NT$，0為尚未設定）','profile-budget',p.monthlyBudget/100,'type="number" step="0.01" min="0" required')}${input('規劃年數','profile-horizon',p.horizon,'type="number" step="1" min="1" max="30" required')}${input('單一標的集中度提醒（%）','profile-concentration',p.concentration,'type="number" step="1" min="5" max="100" required')}<p class="help">這是你自訂的比較條件，不代表公定安全門檻；此預算不會自動從銀行帳戶扣款。</p>${err}<button class="primary full">儲存投資目標</button></form>`);$('#stock-profile-form').onsubmit=e=>{e.preventDefault();try{finish(saveInvestorProfile(state(),{risk:$('#profile-risk').value,monthlyBudget:cents($('#profile-budget').value),horizon:Number($('#profile-horizon').value),concentration:Number($('#profile-concentration').value)}),'投資目標已更新')}catch(e){fail(e)}};}
  function scenarioSheet(){sheet('投入／減碼情境',`<form id="stock-scenario-form">${select('比較標的','scenario-position',data().positions.map(p=>[p.id,p.code+' '+p.name]),data().positions[0]?.id)}${select('情境','scenario-side',[['buy','新增投入'],['sell','減碼回收']],'buy')}${input('試算股數','scenario-shares','','type="number" min="1" step="1" required')}${input('預計成交單價（NT$，空白使用報價）','scenario-price','','type="number" min="0.0001" step="0.0001"')}<div class="row">${input('預估手續費（NT$）','scenario-fee',0,'type="number" min="0" step="0.01" required')}${input('減碼預估交易稅（NT$）','scenario-tax',0,'type="number" min="0" step="0.01" required')}</div>${err}<button class="primary full">比較情境，不入帳</button><div id="scenario-result" role="status"></div></form>`);$('#stock-scenario-form').onsubmit=e=>{e.preventDefault();try{const r=investmentScenario(state(),quotes,{positionId:$('#scenario-position').value,side:$('#scenario-side').value,shares:Number($('#scenario-shares').value),fee:cents($('#scenario-fee').value),tax:cents($('#scenario-tax').value),executionPrice4:$('#scenario-price').value?price4($('#scenario-price').value):undefined});$('#stock-error').textContent='';$('#scenario-result').innerHTML=`<div class="notice" style="margin-top:18px">持股：${r.afterShares}股<br>比重：${r.beforeWeight.toFixed(1)}% → ${r.afterWeight.toFixed(1)}%<br>預估${r.cashChange<0?'投入':'回收'}：<span class="sensitive">${money(Math.abs(r.cashChange))}</span>${r.overBudget?'<br>超過你設定的每月投入預算。':''}</div><p class="help">比例依股票部位目前報價估值，不含投入／回收後的現金；成交價格、費稅與價格變動會影響實際結果。這是試算，沒有記帳或下單。</p>`;}catch(e){fail(e)}};}
  function coachContext(){const f=coachFacts(state(),quotes),p=f.portfolio;return {kind:'investment-coach-v1',date:today(),priceType:'dated-close-or-manual-not-realtime',profile:p.profile,holdings:p.rows.map(r=>({code:r.code,name:r.name,market:r.market,kind:r.kind,shares:r.shares,costCents:r.cost,marketValueCents:r.value,price:r.quote?{price4:r.quote.price4,date:r.quote.date,source:r.quote.source}:null,unrealizedCents:r.unrealized,realizedCents:r.realized,dividendCents:r.dividends})),computed:{marketValueCents:p.value,totalGainCents:p.totalGain,missingPrices:p.missingPrices,missingCosts:p.missingCost,unknownSales:p.unknownSales,largestWeightPercent:f.weight},findings:f.findings};}
  function coachSheet(){const context=coachContext();sheet('請 AI 整理投資選項',`<p class="notice">按下分析，會將本次股票代號、股數、成本、報價與投資目標摘要傳送給 Google。其他帳目與原始截圖不會附上。</p><label class="field">你想討論什麼？<textarea id="stock-coach-question" rows="3" maxlength="1000" placeholder="例如：依我的預算，下個月有哪些做法可以比較？"></textarea></label><details><summary>查看本次傳送的投資摘要</summary><pre class="stock-context">${E(JSON.stringify(context,null,2))}</pre></details>${err}<p id="stock-ai-status" class="help" role="status"></p><button class="primary full" id="stock-coach-run" style="margin-top:18px">傳送持股摘要給 Google，產生分析</button><button class="text-btn" id="stock-ai-cancel">取消本次分析</button>`);const g=generation,key=scope();controller=new AbortController();$('#stock-ai-cancel').onclick=()=>{cancel();$('#sheet').close();};$('#stock-coach-run').onclick=async()=>{const b=$('#stock-coach-run');b.disabled=true;try{const result=await c.runAI('stockCoach',$('#stock-coach-question').value,null,context,{signal:controller.signal,onStatus:s=>{if(g===generation&&$('#stock-ai-status'))$('#stock-ai-status').textContent=s.message}});if(g!==generation||key!==scope())return;sheet('AI 投資教練 · 待你判斷',`<div class="notice">${E(result.summary)}</div><p class="help">依送出當下 ${context.date} 的持股與標示日期價格分析，未查詢新聞、財報或即時行情。</p><h3>需要留意</h3>${result.risks.map(s=>`<p class="help">• ${E(s)}</p>`).join('')}<h3>可比較的做法</h3>${result.options.map(o=>`<div class="match-card"><h3>${E(o.title)}</h3><p>理由：${E(o.reason)}</p><p class="help">條件：${E(o.condition)}<br>代價：${E(o.tradeoff)}</p></div>`).join('')}${result.questions.length?'<h3>還需要補充</h3>'+result.questions.map(s=>`<p class="help">${E(s)}</p>`).join(''):''}<p class="help">AI可能解讀錯誤，請回持股表核對數字。沒有執行記帳或下單。</p>`);}catch(e){if(g===generation)fail(e)}finally{if(b.isConnected)b.disabled=false;}};}
  async function readPhotos(files){if(!files.length||files.length>6)throw Error('一次請選擇1至6張圖片');const images=[];for(const file of files){if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('每張需為10MB內的 JPG、PNG 或 WebP');const bitmap=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();images.push(canvas.toDataURL('image/jpeg',.86));}if(images.reduce((n,v)=>n+v.length,0)>16*1024*1024)throw Error('縮圖合計過大，請減少圖片張數');return images;}
  function importSheet(){sheet('多張股票截圖匯入',`<p class="notice">可一次選1至6張券商持股／成交／股利截圖。先裁掉姓名、帳號等資訊；按下辨識後，選取圖片會傳送 Google。結果先核對，不自動記帳。</p><button class="secondary" id="stock-photo-pick">選擇截圖（最多6張）</button><input type="file" id="stock-photos" multiple accept="image/jpeg,image/png,image/webp" hidden><div id="stock-photo-preview" class="stock-photo-grid"></div><p id="stock-import-status" role="status" class="help">尚未選擇圖片。圖片僅供這次辨識，不寫入帳本、備份或 GitHub。</p>${err}<button class="primary full" id="stock-image-run" disabled>傳送選取圖片給 Google，辨識股票</button><button class="text-btn" id="stock-image-cancel">取消本次辨識</button>`);const key=scope(),g=generation;let photoVersion=0;controller=new AbortController();const current=()=>key===scope()&&g===generation&&!!$('#stock-import-status');$('#stock-photo-pick').onclick=()=>$('#stock-photos').click();$('#stock-image-cancel').onclick=()=>{cancel();$('#sheet').close();};$('#stock-photos').onchange=async e=>{const files=[...e.target.files],version=++photoVersion;controller?.abort();controller=new AbortController();selectedImages=[];$('#stock-image-run').disabled=true;try{const images=await readPhotos(files);if(!current()||version!==photoVersion)return;selectedImages=images;$('#stock-photo-preview').innerHTML=images.map((_,i)=>`<div><img alt="待辨識截圖 ${i+1}"><small>第 ${i+1} 張</small></div>`).join('');$$('#stock-photo-preview img').forEach((el,i)=>el.src=images[i]);$('#stock-import-status').textContent=`已選${images.length}張；請確認沒有敏感資訊，再按辨識。`;$('#stock-image-run').disabled=false;}catch(e){if(current())fail(e)}finally{e.target.value='';}};
    $('#stock-image-run').onclick=async()=>{if(!selectedImages.length)return;const b=$('#stock-image-run'),version=photoVersion;b.disabled=true;$('#stock-photo-pick').disabled=true;try{const rows=await c.runAI('stockImage','',selectedImages,null,{signal:controller.signal,onStatus:s=>{if(current())$('#stock-import-status').textContent=s.message}});if(!current()||version!==photoVersion)return;if(!rows.length)throw Error('沒有辨識到股票紀錄，可改用手動新增');reviewRows(rows);}catch(e){if(current())fail(e)}finally{if(b.isConnected)b.disabled=false;if($('#stock-photo-pick'))$('#stock-photo-pick').disabled=false;}};
  }
  function reviewRows(rows){sheet('核對截圖辨識結果',`<p class="notice">持股庫存只建立一次起點；已存在的股票不會把截圖股數再相加。成本、日期、股／張及費稅請核對。未知欄位不由 AI 補猜。</p><form id="stock-import-review"><div class="stock-import-rows">${rows.map((r,i)=>{const exists=data().positions.some(p=>p.market===r.market&&p.code===r.code),duplicate=r.type==='snapshot'&&exists;let shares=null,cost=r.totalCost;try{shares=stockShares(r.quantity,r.unit);if(r.type==='snapshot'&&cost===null&&r.unitPrice!==null)cost=stockGross(shares,price4(r.unitPrice))/100;}catch{}return `<fieldset data-stock-row="${i}" class="match-card"><legend><label><input type="checkbox" data-field="include" ${duplicate?'':'checked'}> 第${i+1}筆 · 圖片${r.imageIndex||'?'} ${duplicate?'（已有持股，預設略過）':''}</label></legend><p class="help">${E(r.warning||'請確認畫面讀取內容。')}${r.totalCost===null&&cost!==null?' 成本由均價×股數推算，可能未含費用。':''}${r.fee===null||r.tax===null?' 費稅未辨識時預填0，請確認。':''}</p><div class="row">${reviewSelect('類型','type',[['unknown','請確認'],['snapshot','目前持股'],['buy','買進成交'],['sell','賣出成交'],['dividend','實收股利']],r.type)}${reviewSelect('市場','market',[['unknown','請確認'],['TWSE','上市'],['TPEX','上櫃']],r.market)}</div><div class="row">${reviewInput('代號','code',r.code)}${reviewInput('名稱','name',r.name)}</div>${reviewSelect('股票類型','kind',[['unknown','待確認'],['stock','股票'],['etf','ETF']],r.kind)}${reviewInput('日期（起點／成交／入帳）','date',r.date,'date')}<div class="row">${reviewInput('數量','quantity',r.quantity??'','number','step="any" min="0.001"')}${reviewSelect('單位','unit',[['unknown','請確認'],['shares','股'],['lots','張']],r.unit)}</div><div class="row">${reviewInput('單股成交／平均成本價','price',r.unitPrice??'','number','step="0.0001" min="0.0001"')}${reviewInput('持股取得總成本（未知留空）','cost',cost??'','number','step="0.01" min="0"')}</div><div class="row">${reviewInput('手續費','fee',r.fee??0,'number','step="0.01" min="0"')}${reviewInput('交易稅','tax',r.tax??0,'number','step="0.01" min="0"')}</div>${reviewInput('實收股利（股利列才填）','dividend',r.netDividend??'','number','step="0.01" min="0.01"')}<label class="check"><input type="checkbox" data-field="allowDuplicate">這是另一筆相同成交，仍要匯入（不適用持股庫存）</label></fieldset>`;}).join('')}</div>${err}<button class="primary full">確認選取項目並匯入</button><p class="help">日期先後不同會按日期匯入；同日依畫面順序處理。若有同日多筆買賣順序不符，請分批選取，或改用手動紀錄。</p></form>`);const key=scope();$('#stock-import-review').onsubmit=e=>{e.preventDefault();try{if(key!==scope())throw Error('帳號已切換，請重新匯入');const selected=[];$$('[data-stock-row]').forEach(el=>{const f=name=>el.querySelector('[data-field="'+name+'"]');if(!f('include').checked)return;const type=f('type').value;if(type==='unknown')throw Error('請確認每筆資料類型');const row={type,market:f('market').value,code:f('code').value.trim().toUpperCase(),name:f('name').value.trim(),kind:f('kind').value,date:f('date').value,allowDuplicate:f('allowDuplicate').checked};if(type!=='dividend')row.shares=stockShares(f('quantity').value,f('unit').value);if(type==='snapshot')row.cost=f('cost').value.trim()===''?null:cents(f('cost').value);if(['buy','sell'].includes(type))Object.assign(row,{price4:price4(f('price').value),fee:cents(f('fee').value||0),tax:type==='sell'?cents(f('tax').value||0):0});if(type==='dividend')row.amount=cents(f('dividend').value);selected.push(row);});if(!selected.length)throw Error('請至少選取一筆');if(selected.some(r=>r.allowDuplicate)&&!confirm('你已選擇允許相同成交再次匯入，請確認不是重複截圖，確定繼續？'))return;selected.sort((a,b)=>a.date.localeCompare(b.date));const result=importStockRows(state(),selected);finish(result.state,`已核對匯入，略過${result.duplicates}筆重複資料；未新增一般收支`);}catch(e){fail(e)}};}
  function reviewInput(label,field,value='',type='text',extra=''){return `<label class="field">${label}<input data-field="${field}" value="${E(value)}" type="${type}" ${type==='date'?'max="'+today()+'"':''} ${extra}></label>`;}
  function reviewSelect(label,field,options,value){return `<label class="field">${label}<select data-field="${field}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`;}
  function bind(){
    $$('[data-stock-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.stockTab;c.render()});$('#stock-refresh')?.addEventListener('click',loadQuotes);$('#stock-new')?.addEventListener('click',()=>positionSheet());$('#stock-import')?.addEventListener('click',importSheet);$('#stock-event-add')?.addEventListener('click',()=>eventSheet());$('#stock-profile')?.addEventListener('click',profileSheet);$('#stock-scenario')?.addEventListener('click',scenarioSheet);$('#stock-ai-coach')?.addEventListener('click',coachSheet);$('#stock-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;c.render();$('#stock-search').focus();$('#stock-search').setSelectionRange(pos,pos)});$$('[data-stock-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.stockDetail));$$('[data-stock-trade]').forEach(b=>b.onclick=()=>eventSheet(b.dataset.stockTrade));$$('[data-stock-price]').forEach(b=>b.onclick=()=>priceSheet(b.dataset.stockPrice));$$('[data-stock-event-edit]').forEach(b=>b.onclick=()=>eventSheet(null,b.dataset.stockEventEdit));$$('[data-stock-event-delete]').forEach(b=>b.onclick=()=>{if(confirm('刪除此投資紀錄？若使後續賣出超過持股將停止；建議先下載完整備份。'))try{finish(deleteStockEvent(state(),b.dataset.stockEventDelete),'投資紀錄已刪除')}catch(e){toast(e.message)}});
  }
  return {page,bind,homePanel,init:loadQuotes,cancel};
}
